// ---------------------------------------------------------------- seed policies
// Each rule carries the measurement that justifies it. A rule nobody can justify is a
// rule nobody will maintain, and grounding is the first thing a compliance reader asks for.
db.policies.replaceOne({_id: 'pol:require_source_quote:1'}, Object.assign({
  "_id": "pol:require_source_quote:1",
  "ruleId": "require_source_quote",
  "version": 1,
  "appliesTo": [
    "claim.write",
    "rung.assert",
    "record.create"
  ],
  "effect": "deny",
  "predicate": "missing_source_quote",
  "params": {
    "minLength": 25
  },
  "reason": "A figure may not be written without the verbatim sentence it was read from.",
  "grounding": "Reviewers judge an assay on evidence provenance, not on a headline number. An uncited figure is worse than a blank, because a blank prompts a check and a bare number does not.",
  "active": true
}, {createdAt: new Date()}), {upsert: true});
db.policies.replaceOne({_id: 'pol:reject_unverifiable_fragment:1'}, Object.assign({
  "_id": "pol:reject_unverifiable_fragment:1",
  "ruleId": "reject_unverifiable_fragment",
  "version": 1,
  "appliesTo": [
    "claim.write"
  ],
  "effect": "deny",
  "predicate": "fragment_unverified",
  "params": {},
  "reason": "The quoted fragment could not be located in the retained source text, so the figure is not verifiable at source.",
  "grounding": "94 of 859 real records carry a performance fragment that is not a substring of the retained excerpt. Those figures cannot be confirmed without re-fetching the source.",
  "active": true
}, {createdAt: new Date()}), {upsert: true});
db.policies.replaceOne({_id: 'pol:escalate_ambiguous_claim:1'}, Object.assign({
  "_id": "pol:escalate_ambiguous_claim:1",
  "ruleId": "escalate_ambiguous_claim",
  "version": 1,
  "appliesTo": [
    "claim.write"
  ],
  "effect": "escalate",
  "predicate": "claim_ambiguous",
  "params": {},
  "reason": "More than one candidate figure appears in the source, so a single value cannot be chosen without a human reading the sentence.",
  "grounding": "46 of 859 records carry more than one distinct candidate sensitivity. Hand audit found inversions and figures stolen from an adjacent metric in exactly these cases.",
  "active": true
}, {createdAt: new Date()}), {upsert: true});
db.policies.replaceOne({_id: 'pol:deny_rung4_from_literature:1'}, Object.assign({
  "_id": "pol:deny_rung4_from_literature:1",
  "ruleId": "deny_rung4_from_literature",
  "version": 1,
  "appliesTo": [
    "rung.assert",
    "record.create",
    "claim.write"
  ],
  "effect": "deny",
  "predicate": "rung_from_literature",
  "params": {
    "minRung": 4
  },
  "reason": "A regulatory or reimbursement rung may only be asserted from a regulator or an HTA body, never inferred from literature.",
  "grounding": "Regulatory vocabulary inside research abstracts is about 85 per cent false positive. 'FDA-approved' in an abstract almost always describes the therapy, not the assay. Also measured: 'uptake' meaning Fc-mediated cellular uptake, and 'CMS' meaning screening eligibility criteria rather than a coverage decision.",
  "active": true
}, {createdAt: new Date()}), {upsert: true});
db.policies.replaceOne({_id: 'pol:require_human_for_rankable:1'}, Object.assign({
  "_id": "pol:require_human_for_rankable:1",
  "ruleId": "require_human_for_rankable",
  "version": 1,
  "appliesTo": [
    "claim.write",
    "claim.verify"
  ],
  "effect": "escalate",
  "predicate": "rankable_by_agent",
  "params": {},
  "reason": "Only a human may mark a figure rankable, because machine-read figures are about half wrong.",
  "grounding": "Hand audit of 20 machine-parsed sensitivity and specificity pairs: 10 correct, 7 wrong, 3 that should have been refused. Measured accuracy 50 per cent. Failure modes: metric inversion, theft from an adjacent metric, confidence-interval leakage, ranges split instead of refused.",
  "active": true
}, {createdAt: new Date()}), {upsert: true});
